SourceCode.Declaration:
/// <summary>
/// uploadSample response. Success also when the sample was already there or the item is full - the device can delete its copy either way.
/// </summary>
[DataContractAttribute]
class HSMobileOpsAiSampleResponse
{
    boolean success;
    str errorCode;
    boolean stored;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Stored')]
public boolean parmStored(boolean _value = stored)
{
    stored = _value;
    return stored;
}
